function minimumSum(nums) {
  const n = nums.length;
  const suffixMin = new Array(n);
  suffixMin[n - 1] = nums[n - 1];
  for (let k = n - 2; k >= 0; k--) {
    suffixMin[k] = Math.min(nums[k], suffixMin[k + 1]);
  }
  let best = Infinity;
  let prefixMin = nums[0];
  for (let j = 1; j < n - 1; j++) {
    const left = prefixMin;
    const right = suffixMin[j + 1];
    if (left < nums[j] && right < nums[j]) {
      best = Math.min(best, left + nums[j] + right);
    }
    prefixMin = Math.min(prefixMin, nums[j]);
  }
  return best === Infinity ? -1 : best;
}

