function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const style = Math.floor(rand() * 3);
    if (style === 0) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 100000000))];
    if (style === 1) {
      // A valley: falling then rising, so there is no mountain at all.
      const bottom = Math.floor(rand() * n);
      return [Array.from({ length: n }, (_, i) => 1 + Math.abs(i - bottom) * 1000)];
    }
    return [Array.from({ length: n }, (_, i) => 100000000 - i * 1000 - Math.floor(rand() * 5000))];
  }
  const n = 3 + Math.floor(rand() * 6);
  const top = rand() < 0.8 ? 6 : 100000000;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
